const ce = React.createElement;
const cx = width / 2;
const cy = height / 2;
const R = Math.min(width, height) * 0.44;
const doorScale = spring({ frame, fps, config: { damping: 14, stiffness: 80 } });
const pulse = 0.5 + 0.5 * Math.sin(frame * 0.1);
const companies = ['Apple', 'Google', 'Microsoft', 'NVIDIA', 'JPMorgan', 'CrowdStrike', 'AWS', 'Cisco'];
const clOp = interpolate(frame, [45, 65], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
const gwOp = interpolate(frame, [60, 80], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
const rot = interpolate(frame, [0, Math.max(1, durationInFrames)], [0, 3], { extrapolateRight: 'clamp' });

const traces = Array.from({ length: 16 }, function(_, i) {
  const a = (i / 16) * Math.PI * 2;
  const r1 = R * (0.22 + (i % 3) * 0.05);
  const r2 = R * (0.58 + (i % 2) * 0.08);
  const mx = Math.cos(a + 0.1) * R * 0.4;
  const my = Math.sin(a + 0.1) * R * 0.4;
  const d = i * 2;
  const op = interpolate(frame, [12 + d, Math.max(13 + d, 30 + d)], [0, pulse * 0.5 + 0.15], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  return ce('path', { key: 't' + i, d: 'M' + (Math.cos(a) * r1) + ',' + (Math.sin(a) * r1) + 'L' + mx + ',' + my + 'L' + (Math.cos(a) * r2) + ',' + (Math.sin(a) * r2), stroke: D.green, strokeWidth: 1.2, fill: 'none', opacity: op });
});

const rivets = Array.from({ length: 24 }, function(_, i) {
  const a = (i / 24) * Math.PI * 2;
  return ce('circle', { key: 'r' + i, cx: Math.cos(a) * R * 0.96, cy: Math.sin(a) * R * 0.96, r: 4, fill: D.text_dim, opacity: 0.5 });
});

const bolts = companies.map(function(name, i) {
  const angle = (i / 8) * Math.PI * 2 - Math.PI / 2;
  const bx = Math.cos(angle) * R * 0.78;
  const by = Math.sin(angle) * R * 0.78;
  const delay = 40 + i * 10;
  const s = spring({ frame: frame - delay, fps, config: { damping: 10, stiffness: 200 } });
  const hexRot = interpolate(s, [0, 1], [120, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const bR = 34;
  const fs = name.length > 8 ? 8 : name.length > 6 ? 9.5 : 11;
  return ce('g', { key: 'b' + i, transform: 'translate(' + bx + ',' + by + ')', opacity: s },
    ce('circle', { cx: 0, cy: 0, r: bR, fill: D.surface, stroke: D.white, strokeWidth: 2.5 }),
    ce('polygon', {
      points: Array.from({ length: 6 }, function(_, j) {
        const ha = (j / 6) * Math.PI * 2 + hexRot * Math.PI / 180;
        return (Math.cos(ha) * 16) + ',' + (Math.sin(ha) * 16);
      }).join(' '),
      fill: 'none', stroke: D.green, strokeWidth: 1.5, opacity: 0.7
    }),
    ce('text', { x: 0, y: 4, textAnchor: 'middle', fill: D.white, fontSize: fs, fontFamily: D.font_mono, fontWeight: 'bold' }, name)
  );
});

return ce('div', { style: { position: 'absolute', inset: 0, backgroundColor: D.bg, overflow: 'hidden' } },
  ce('div', { style: { position: 'absolute', inset: 0, zIndex: 5, background: 'radial-gradient(ellipse at center, transparent 40%, rgba(0,0,0,0.7) 100%)', pointerEvents: 'none' } }),
  ce('div', { style: { position: 'absolute', inset: 0, zIndex: 6, background: 'repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,0,0,0.04) 2px, rgba(0,0,0,0.04) 4px)', pointerEvents: 'none' } }),
  ce('svg', { width: width, height: height, viewBox: '0 0 ' + width + ' ' + height, style: { position: 'absolute', top: 0, left: 0, transform: 'scale(' + doorScale + ')', transformOrigin: cx + 'px ' + cy + 'px' } },
    ce('defs', null,
      ce('filter', { id: 'gl' },
        ce('feGaussianBlur', { stdDeviation: 4, result: 'b' }),
        ce('feMerge', null, ce('feMergeNode', { in: 'b' }), ce('feMergeNode', { in: 'SourceGraphic' }))
      ),
      ce('radialGradient', { id: 'dg', cx: '50%', cy: '45%', r: '50%' },
        ce('stop', { offset: '0%', stopColor: D.surface }),
        ce('stop', { offset: '90%', stopColor: D.bg })
      )
    ),
    ce('g', { transform: 'translate(' + cx + ',' + cy + ') rotate(' + rot + ')' },
      ce('circle', { cx: 0, cy: 0, r: R, fill: 'url(#dg)', stroke: D.text_dim, strokeWidth: 8 }),
      ce('circle', { cx: 0, cy: 0, r: R * 0.93, fill: 'none', stroke: D.text_dim, strokeWidth: 2, opacity: 0.35 }),
      ce('circle', { cx: 0, cy: 0, r: R * 0.93, fill: 'none', stroke: D.green, strokeWidth: 1, opacity: pulse * 0.25, filter: 'url(#gl)' }),
      ...rivets,
      ce('g', { filter: 'url(#gl)' }, ...traces),
      ce('g', { transform: 'rotate(' + (-rot) + ')' },
        ce('rect', { x: -R * 0.38, y: -R * 0.18, width: R * 0.76, height: R * 0.36, rx: 6, fill: D.bg, stroke: D.text_dim, strokeWidth: 2, opacity: 0.95 }),
        ce('text', { x: 0, y: -R * 0.01, textAnchor: 'middle', fill: D.red, fontSize: R * 0.11, fontFamily: D.font_display, fontWeight: 'bold', letterSpacing: '10px', opacity: clOp }, 'CLASSIFIED'),
        ce('text', { x: 0, y: R * 0.1, textAnchor: 'middle', fill: D.amber, fontSize: R * 0.055, fontFamily: D.font_mono, letterSpacing: '5px', opacity: gwOp }, 'PROJECT GLASSWING')
      ),
      ...bolts
    )
  )
);
